-- Name: ai_usage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_usage (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    organization_id uuid NOT NULL,
    feature character varying(80) NOT NULL,
    task_key character varying(80),
    provider character varying(32) NOT NULL,
    model character varying(80) NOT NULL,
    prompt_tokens integer DEFAULT 0 NOT NULL,
    completion_tokens integer DEFAULT 0 NOT NULL,
    total_tokens integer DEFAULT 0 NOT NULL,
    latency_ms integer DEFAULT 0 NOT NULL,
    outcome character varying(16) NOT NULL,
    cost_estimate_paise bigint DEFAULT 0 NOT NULL,
    pii_redacted boolean DEFAULT false NOT NULL,
    correlation_type character varying(40),
    correlation_id uuid,
    error_code character varying(40),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT ck_ai_usage_outcome CHECK (((outcome)::text = ANY ((ARRAY['SUCCESS'::character varying, 'BLOCKED'::character varying, 'ERROR'::character varying, 'DISABLED'::character varying])::text[]))),
    CONSTRAINT ck_ai_usage_tokens CHECK (((prompt_tokens >= 0) AND (completion_tokens >= 0) AND (total_tokens >= 0)))
);


