--
-- Name: billing_invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    organization_id uuid NOT NULL,
    order_id uuid,
    subscription_id uuid,
    invoice_number character varying(60) NOT NULL,
    financial_year character varying(9) NOT NULL,
    sequence_number integer NOT NULL,
    status character varying(16) DEFAULT 'ISSUED'::character varying NOT NULL,
    issue_date date DEFAULT CURRENT_DATE NOT NULL,
    due_date date,
    paid_at timestamp with time zone,
    bill_to_name character varying(250) NOT NULL,
    bill_to_address jsonb DEFAULT '{}'::jsonb NOT NULL,
    bill_to_gstin character varying(15),
    bill_to_email public.citext,
    line_items jsonb DEFAULT '[]'::jsonb NOT NULL,
    subtotal_paise bigint NOT NULL,
    discount_paise bigint DEFAULT 0 NOT NULL,
    cgst_paise bigint DEFAULT 0 NOT NULL,
    sgst_paise bigint DEFAULT 0 NOT NULL,
    igst_paise bigint DEFAULT 0 NOT NULL,
    total_paise bigint NOT NULL,
    currency character varying(3) DEFAULT 'INR'::character varying NOT NULL,
    sac_code character varying(12) DEFAULT '998314'::character varying NOT NULL,
    place_of_supply character varying(80),
    notes character varying(1000),
    pdf_file_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT ck_billing_invoices_amounts CHECK (((subtotal_paise >= 0) AND (discount_paise >= 0) AND (cgst_paise >= 0) AND (sgst_paise >= 0) AND (igst_paise >= 0) AND (total_paise = ((((subtotal_paise - discount_paise) + cgst_paise) + sgst_paise) + igst_paise)))),
    CONSTRAINT ck_billing_invoices_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ISSUED'::character varying, 'PAID'::character varying, 'VOID'::character varying, 'REFUNDED'::character varying])::text[]))),
    CONSTRAINT ck_billing_invoices_tax_exclusive CHECK ((NOT ((igst_paise > 0) AND ((cgst_paise > 0) OR (sgst_paise > 0)))))
);


