--

CREATE TABLE public.billing_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    organization_id uuid NOT NULL,
    subscription_id uuid,
    plan_id uuid,
    purpose character varying(32) NOT NULL,
    amount_paise bigint NOT NULL,
    tax_paise bigint DEFAULT 0 NOT NULL,
    total_paise bigint NOT NULL,
    currency character varying(3) DEFAULT 'INR'::character varying NOT NULL,
    status character varying(16) DEFAULT 'CREATED'::character varying NOT NULL,
    razorpay_order_id character varying(80),
    razorpay_payment_id character varying(80),
    receipt character varying(80) NOT NULL,
    notes jsonb DEFAULT '{}'::jsonb NOT NULL,
    failure_reason character varying(500),
    captured_at timestamp with time zone,
    initiated_by uuid,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT ck_billing_orders_amounts CHECK (((amount_paise >= 0) AND (tax_paise >= 0) AND (total_paise = (amount_paise + tax_paise)))),
    CONSTRAINT ck_billing_orders_purpose CHECK (((purpose)::text = ANY ((ARRAY['SUBSCRIPTION_NEW'::character varying, 'SUBSCRIPTION_RENEWAL'::character varying, 'SEAT_ADDITION'::character varying, 'UPGRADE'::character varying, 'ONE_TIME'::character varying])::text[]))),
    CONSTRAINT ck_billing_orders_status CHECK (((status)::text = ANY ((ARRAY['CREATED'::character varying, 'ATTEMPTED'::character varying, 'CAPTURED'::character varying, 'FAILED'::character varying, 'REFUNDED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[])))
);


