    CONSTRAINT ck_billing_payments_status CHECK (((status)::text = ANY ((ARRAY['CREATED'::character varying, 'AUTHORIZED'::character varying, 'CAPTURED'::character varying, 'REFUNDED'::character varying, 'FAILED'::character varying])::text[])))
);


