    CONSTRAINT ck_billing_plans_amounts CHECK (((amount_paise >= 0) AND (per_seat_paise >= 0) AND (included_seats >= 0))),
    CONSTRAINT ck_billing_plans_interval CHECK (((interval_type)::text = ANY ((ARRAY['MONTHLY'::character varying, 'ANNUAL'::character varying, 'ONE_TIME'::character varying, 'CUSTOM'::character varying])::text[]))),
    CONSTRAINT ck_billing_plans_max_seats CHECK (((max_seats IS NULL) OR (max_seats >= included_seats)))
);


--
-- Name: billing_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    organization_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    status character varying(24) DEFAULT 'TRIALING'::character varying NOT NULL,
