    current_period_end timestamp with time zone NOT NULL,
    trial_ends_at timestamp with time zone,
    cancel_at_period_end boolean DEFAULT false NOT NULL,
    cancelled_at timestamp with time zone,
    cancellation_reason character varying(500),
    grace_period_ends_at timestamp with time zone,
    failed_payment_count integer DEFAULT 0 NOT NULL,
    last_payment_at timestamp with time zone,
    next_billing_at timestamp with time zone,
    razorpay_subscription_id character varying(80),
    razorpay_customer_id character varying(80),
    locked_amount_paise bigint NOT NULL,
    locked_per_seat_paise bigint DEFAULT 0 NOT NULL,
    currency character varying(3) DEFAULT 'INR'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    pending_plan_id uuid,
    pending_seats integer,
    pending_change_at timestamp with time zone,
    next_dunning_retry_at timestamp with time zone,
    razorpay_token_id character varying(80),
    CONSTRAINT ck_subscriptions_failed_count CHECK ((failed_payment_count >= 0)),
    CONSTRAINT ck_subscriptions_pending_seats CHECK (((pending_seats IS NULL) OR (pending_seats > 0))),
    CONSTRAINT ck_subscriptions_period CHECK ((current_period_end > current_period_start)),
    CONSTRAINT ck_subscriptions_seats CHECK ((seats > 0)),
    CONSTRAINT ck_subscriptions_status CHECK (((status)::text = ANY ((ARRAY['TRIALING'::character varying, 'ACTIVE'::character varying, 'PAST_DUE'::character varying, 'PAUSED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[])))
);


