);


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    email public.citext NOT NULL,
    email_verified_at timestamp with time zone,
    phone character varying(32),
    phone_verified_at timestamp with time zone,
    password_hash character varying(120),
    password_changed_at timestamp with time zone,
    full_name character varying(160) NOT NULL,
    display_name character varying(80),
    avatar_url character varying(500),
    job_title character varying(120),
    timezone character varying(64) DEFAULT 'Asia/Kolkata'::character varying NOT NULL,
    locale character varying(16) DEFAULT 'en-IN'::character varying NOT NULL,
    status character varying(24) DEFAULT 'ACTIVE'::character varying NOT NULL,
    platform_admin boolean DEFAULT false NOT NULL,
    failed_login_attempts integer DEFAULT 0 NOT NULL,
    locked_until timestamp with time zone,
    last_login_at timestamp with time zone,
    last_active_at timestamp with time zone,
    default_organization_id uuid,
    notification_prefs jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    deleted_at timestamp with time zone,
    CONSTRAINT ck_users_email_shape CHECK ((POSITION(('@'::text) IN (email)) > 1)),
    CONSTRAINT ck_users_failed_attempts CHECK ((failed_login_attempts >= 0)),
    CONSTRAINT ck_users_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INVITED'::character varying, 'DISABLED'::character varying, 'LOCKED'::character varying])::text[])))
);


