INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('8181c8cc-fbf6-4506-9ee6-3b2fb413f4c2', 0, NULL, 'auth.magic-link', 'en', 'Sign-in link', 'Passwordless sign-in link', 'Your Prabhix sign-in link', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Sign in to Prabhix</h1><p style="font-size:15px;line-height:1.6;margin:0 0 24px">Hello <span th:text="${name}">there</span>, use the button below to sign in. This link works once and expires in <span th:text="${expiryMinutes}">15</span> minutes.</p><p style="margin:0 0 28px"><a th:href="${link}" href="#" style="background:#0e7490;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-size:15px;display:inline-block">Sign in</a></p><p style="font-size:13px;color:#6b6b7b;line-height:1.6;margin:0">If you did not request this, you can safely ignore this email. Nobody can sign in without opening the link.</p></div>', NULL, '[{"name": "name", "example": "Priya", "required": true}, {"name": "link", "example": "https://app.prabhixtechnologies.com/auth/magic?token=...", "required": true}, {"name": "expiryMinutes", "example": "15", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:07.991873+00', '2026-08-30 03:05:07.991873+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('db270938-6ee6-480d-8ab7-49a35f05fede', 0, NULL, 'auth.otp', 'en', 'One-time code', 'Numeric code for email or SMS verification', 'Your Prabhix verification code', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Your verification code</h1><p style="font-size:32px;letter-spacing:8px;font-weight:700;margin:0 0 20px;color:#0e7490" th:text="${code}">000000</p><p style="font-size:14px;color:#6b6b7b;line-height:1.6;margin:0">Expires in <span th:text="${expiryMinutes}">10</span> minutes. Never share this code with anyone, including someone claiming to be from Prabhix.</p></div>', NULL, '[{"name": "code", "example": "482913", "required": true}, {"name": "expiryMinutes", "example": "10", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:07.991873+00', '2026-08-30 03:05:07.991873+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('7ac0bec7-f20b-4257-b3e9-2326a554c568', 0, NULL, 'org.invite', 'en', 'Organization invitation', 'Invite someone to join an organization', '[(${inviterName})] invited you to [(${organizationName})] on Prabhix', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">You have been invited</h1><p style="font-size:15px;line-height:1.6;margin:0 0 20px"><strong th:text="${inviterName}">A colleague</strong> invited you to join <strong th:text="${organizationName}">their organization</strong> on Prabhix as <span th:text="${roleName}">a member</span>.</p><blockquote th:if="${message}" style="border-left:3px solid #0e7490;margin:0 0 20px;padding:4px 0 4px 16px;font-size:14px;color:#3f3f52" th:text="${message}"></blockquote><p style="margin:0 0 28px"><a th:href="${link}" href="#" style="background:#0e7490;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-size:15px;display:inline-block">Accept invitation</a></p><p style="font-size:13px;color:#6b6b7b;margin:0">This invitation expires on <span th:text="${expiresOn}">a week from now</span>.</p></div>', NULL, '[{"name": "inviterName", "example": "Priya Sharma", "required": true}, {"name": "organizationName", "example": "Acme Corp", "required": true}, {"name": "roleName", "example": "Agent", "required": true}, {"name": "link", "example": "https://app.prabhixtechnologies.com/invite/...", "required": true}, {"name": "expiresOn", "example": "5 September 2026", "required": true}, {"name": "message", "example": "Looking forward to having you on the team.", "required": false}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:07.991873+00', '2026-08-30 03:05:07.991873+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('3c4b47a7-7ee5-414c-af3a-eae4ce614687', 0, NULL, 'billing.payment-succeeded', 'en', 'Payment receipt', 'Confirmation after a successful payment', 'Payment received — invoice [(${invoiceNumber})]', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Payment received</h1><p style="font-size:15px;line-height:1.6;margin:0 0 20px">Thank you. We have received <strong th:text="${amount}">₹0</strong> for <span th:text="${planName}">your plan</span>.</p><table style="font-size:14px;border-collapse:collapse;margin:0 0 24px"><tr><td style="padding:4px 16px 4px 0;color:#6b6b7b">Invoice</td><td th:text="${invoiceNumber}">PBX-0001</td></tr><tr><td style="padding:4px 16px 4px 0;color:#6b6b7b">Paid on</td><td th:text="${paidOn}">today</td></tr><tr><td style="padding:4px 16px 4px 0;color:#6b6b7b">Next renewal</td><td th:text="${nextRenewal}">in a month</td></tr></table><p style="margin:0"><a th:href="${invoiceUrl}" href="#" style="color:#0e7490;font-size:14px">Download invoice</a></p></div>', NULL, '[{"name": "amount", "example": "₹2,499.00", "required": true}, {"name": "planName", "example": "Growth (monthly)", "required": true}, {"name": "invoiceNumber", "example": "PBX-2026-0042", "required": true}, {"name": "paidOn", "example": "27 August 2026", "required": true}, {"name": "nextRenewal", "example": "27 September 2026", "required": true}, {"name": "invoiceUrl", "example": "https://app.prabhixtechnologies.com/billing/invoices/...", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:07.991873+00', '2026-08-30 03:05:07.991873+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('8658974e-33c2-4501-8b0f-e91df9734576', 0, NULL, 'billing.payment-failed', 'en', 'Payment failed', 'Dunning notice after a failed renewal', 'Action needed: your Prabhix payment did not go through', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">We could not process your payment</h1><p style="font-size:15px;line-height:1.6;margin:0 0 20px">The payment of <strong th:text="${amount}">₹0</strong> for <span th:text="${planName}">your plan</span> failed. Your workspace stays active until <strong th:text="${graceEndsOn}">the grace period ends</strong>.</p><p style="margin:0 0 24px"><a th:href="${retryUrl}" href="#" style="background:#0e7490;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-size:15px;display:inline-block">Update payment method</a></p><p style="font-size:13px;color:#6b6b7b;margin:0">Attempt <span th:text="${attempt}">1</span> of <span th:text="${maxAttempts}">3</span>. We will try again automatically.</p></div>', NULL, '[{"name": "amount", "example": "₹2,499.00", "required": true}, {"name": "planName", "example": "Growth (monthly)", "required": true}, {"name": "graceEndsOn", "example": "3 September 2026", "required": true}, {"name": "retryUrl", "example": "https://app.prabhixtechnologies.com/billing", "required": true}, {"name": "attempt", "example": "1", "required": true}, {"name": "maxAttempts", "example": "3", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:07.991873+00', '2026-08-30 03:05:07.991873+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('75487ad1-077b-4dbf-9101-23d128f85def', 0, NULL, 'mail.sla-breach', 'en', 'SLA breach alert', 'Sent to mailbox leads when a thread misses its target', 'SLA breached: [(${threadSubject})]', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 12px;color:#b91c1c">SLA breached</h1><p style="font-size:15px;line-height:1.6;margin:0 0 16px"><strong th:text="${threadSubject}">A conversation</strong> in <span th:text="${mailboxName}">an inbox</span> passed its <span th:text="${targetMinutes}">60</span>-minute first-response target.</p><table style="font-size:14px;border-collapse:collapse;margin:0 0 24px"><tr><td style="padding:4px 16px 4px 0;color:#6b6b7b">Customer</td><td th:text="${customerEmail}">someone@example.com</td></tr><tr><td style="padding:4px 16px 4px 0;color:#6b6b7b">Assignee</td><td th:text="${assigneeName}">Unassigned</td></tr><tr><td style="padding:4px 16px 4px 0;color:#6b6b7b">Waiting</td><td th:text="${waitingFor}">2 hours</td></tr></table><p style="margin:0"><a th:href="${threadUrl}" href="#" style="background:#0e7490;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-size:15px;display:inline-block">Open conversation</a></p></div>', NULL, '[{"name": "threadSubject", "example": "Login not working", "required": true}, {"name": "mailboxName", "example": "Support", "required": true}, {"name": "targetMinutes", "example": "60", "required": true}, {"name": "customerEmail", "example": "customer@acme.com", "required": true}, {"name": "assigneeName", "example": "Unassigned", "required": true}, {"name": "waitingFor", "example": "2 hours 14 minutes", "required": true}, {"name": "threadUrl", "example": "https://app.prabhixtechnologies.com/inbox/threads/...", "required": true}]', 'NOTIFICATION', false, true, '2026-08-30 03:05:07.991873+00', '2026-08-30 03:05:07.991873+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('c2cbd7ce-1976-4502-a209-056e12c10bcd', 0, NULL, 'site.lead-acknowledgement', 'en', 'Enquiry acknowledgement', 'Auto-reply to a marketing site enquiry', 'Thanks for contacting Prabhix Technologies', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Thanks for getting in touch</h1><p style="font-size:15px;line-height:1.6;margin:0 0 16px">Hello <span th:text="${name}">there</span>, we have your enquiry and someone from our team will reply within one business day.</p><p style="font-size:14px;color:#6b6b7b;line-height:1.6;margin:0 0 8px">What you sent us:</p><blockquote style="border-left:3px solid #0e7490;margin:0 0 24px;padding:4px 0 4px 16px;font-size:14px;color:#3f3f52" th:text="${message}"></blockquote><p style="font-size:13px;color:#6b6b7b;margin:0">Prabhix Technologies — building software that simplifies business.</p></div>', NULL, '[{"name": "name", "example": "Priya", "required": true}, {"name": "message", "example": "We would like a demo for a 200-agent support team.", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:07.991873+00', '2026-08-30 03:05:07.991873+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('262540cc-a461-490f-b95c-45f38e7325c5', 0, NULL, 'site.newsletter-confirm', 'en', 'Newsletter confirmation', 'Double opt-in confirmation for a marketing-site newsletter signup', 'Confirm your Prabhix subscription', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">One more step</h1><p style="font-size:15px;line-height:1.6;margin:0 0 24px">Confirm this address to start receiving engineering notes and product updates from Prabhix Technologies. We send rarely, and you can leave at any time.</p><p style="margin:0 0 28px"><a th:href="${confirmUrl}" href="#" style="background:#0e7490;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-size:15px;display:inline-block">Confirm subscription</a></p><p style="font-size:13px;color:#6b6b7b;line-height:1.6;margin:0">If you did not sign up, ignore this email and nothing further will be sent. We only add an address once it has been confirmed here.</p></div>', NULL, '[{"name": "confirmUrl", "example": "https://api.prabhixtechnologies.com/api/v1/site/subscribers/confirm?token=...", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:08.625662+00', '2026-08-30 03:05:08.625662+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('4cbec692-503a-48d2-8a64-25eefd09238a', 0, NULL, 'chat.transcript', 'en', 'Chat transcript', 'Sent to a visitor when a chat conversation is closed', 'Your chat with [[${organizationName}]]', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:560px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Chat transcript</h1><p style="font-size:15px;line-height:1.6;margin:0 0 24px">Here is a copy of your recent conversation with us.</p><div th:utext="${transcriptHtml}" style="font-size:14px;line-height:1.7;border-left:3px solid #0e7490;padding-left:16px;margin:0 0 24px"></div><p style="font-size:13px;color:#6b6b7b;margin:0">If you have further questions, reply to this email or start a new chat on our site.</p></div>', NULL, '[{"name": "organizationName", "example": "Acme Corp", "required": true}, {"name": "transcriptHtml", "example": "<p><strong>Agent:</strong> Hello!</p>", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:09.13616+00', '2026-08-30 03:05:09.13616+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('74a34c31-2a08-46cd-989e-13ebc767954d', 0, NULL, 'chat.offline-message', 'en', 'Offline chat message', 'Sent to the support mailbox when no agent is available', 'Offline chat from [[${visitorName}]]', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:560px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Offline chat message</h1><p style="font-size:15px;line-height:1.6;margin:0 0 8px"><strong>From:</strong> <span th:text="${visitorName}">Visitor</span> (<span th:text="${visitorEmail}">email</span>)</p><p style="font-size:15px;line-height:1.6;margin:0 0 24px"><strong>Subject:</strong> <span th:text="${subject}">Subject</span></p><div th:utext="${messageBody}" style="font-size:14px;line-height:1.7;border-left:3px solid #0e7490;padding-left:16px"></div></div>', NULL, '[{"name": "visitorName", "example": "Jane Doe", "required": true}, {"name": "visitorEmail", "example": "jane@example.com", "required": true}, {"name": "subject", "example": "Pricing question", "required": false}, {"name": "messageBody", "example": "Hello, I need help with...", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:09.13616+00', '2026-08-30 03:05:09.13616+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('c4ebc3c6-136d-4c85-a803-dead60457a4e', 0, NULL, 'commerce.order-confirmation', 'en', 'Order confirmation', 'Sent to a storefront customer when payment succeeds', 'Your order [[${orderNumber}]] from [[${organizationName}]]', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:560px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Thank you for your order</h1><p style="font-size:15px;line-height:1.6;margin:0 0 8px">Order <strong th:text="${orderNumber}">ORD-001</strong></p><p style="font-size:15px;line-height:1.6;margin:0 0 24px">Total: <strong th:text="${orderTotal}">₹0.00</strong></p><p style="font-size:14px;line-height:1.7;margin:0 0 24px">You can view your order anytime using the link below.</p><p style="margin:0 0 24px"><a th:href="${orderUrl}" style="color:#0e7490">View order</a></p><p style="font-size:13px;color:#6b6b7b;margin:0">Questions? Reply to this email.</p></div>', NULL, '[{"name": "organizationName", "example": "Acme Corp", "required": true}, {"name": "orderNumber", "example": "ORD/2026-27/000001", "required": true}, {"name": "orderTotal", "example": "₹1,180.00", "required": true}, {"name": "orderUrl", "example": "https://example.com/orders/abc", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:10.075888+00', '2026-08-30 03:05:10.075888+00', NULL, NULL);
INSERT INTO public.mail_templates (id, version, organization_id, template_key, locale, name, description, subject, body_html, body_text, variables, category, tracking_enabled, enabled, created_at, updated_at, created_by, updated_by) VALUES ('2275c190-a07f-4cda-acfe-611d3169b6a8', 0, NULL, 'auth.email-verify', 'en', 'Verify your email', 'Email address verification link', 'Verify your Prabhix email address', '<div style="font-family:''Plus Jakarta Sans'',Segoe UI,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 24px;color:#0B0B12"><h1 style="font-size:20px;margin:0 0 16px">Verify your email</h1><p style="font-size:15px;line-height:1.6;margin:0 0 24px">Hello <span th:text="${name}">there</span>, confirm this address belongs to you. The link works once and expires in <span th:text="${expiryMinutes}">15</span> minutes.</p><p style="margin:0 0 28px"><a th:href="${link}" href="#" style="background:#0e7490;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-size:15px;display:inline-block">Verify email</a></p><p style="font-size:13px;color:#6b6b7b;line-height:1.6;margin:0">If you did not request this, you can safely ignore this email.</p></div>', NULL, '[{"name": "name", "example": "Priya", "required": true}, {"name": "link", "example": "https://app.prabhixtechnologies.com/auth/verify-email?token=...", "required": true}, {"name": "expiryMinutes", "example": "15", "required": true}]', 'TRANSACTIONAL', false, true, '2026-08-30 03:05:10.992261+00', '2026-08-30 03:05:10.992261+00', NULL, NULL);


